function personFit(record, person) {
  if (record.best_for.includes(person)) return 5;
  if (record.secondary_for.includes(person)) return 4;
  return person === "sheluvspaco" ? 3.8 : 3.4;
}

function scheduleItem(tuple, placeById) {
  const [start, end, placeId, priority] = tuple;
  const record = placeById.get(placeId);
  if (!record) throw new Error(`Unknown place ${placeId}`);
  return { start, end, place_id: placeId, priority, reservation: record.reservation };
}

async function main() {
  const [research, weather, geometry, replacements] = await Promise.all([
    readFile(path.join(ROUTE_DIR, "research-raw.json"), "utf8").then(JSON.parse),
    readFile(path.join(ROUTE_DIR, "weather-normals.json"), "utf8").then(JSON.parse),
    readFile(path.join(ROUTE_DIR, "route-geometry.json"), "utf8").then(JSON.parse),
    readFile(path.join(ROUTE_DIR, "replacement-geometry.json"), "utf8").then(JSON.parse)
  ]);
  const replacementGeometryById = new Map(replacements.variants.map((variant) => [variant.id, variant]));
  const images = [];
  const productionPlaces = seedPlaces.map((record) => {
    const raw = research.places[record.id];
    const coordinates = manualCoordinates[record.id] || (raw?.selected_coordinate ? [raw.selected_coordinate.longitude, raw.selected_coordinate.latitude] : null);
    if (!coordinates) throw new Error(`Missing coordinates for ${record.id}`);
    const imageIds = (raw?.selected_images || []).slice(0, 8).map((image, index) => {
      const id = `img-${record.id}-${index + 1}`;
      images.push({
        id, place_id: record.id, title: image.title, description: image.description,
        search_query: image.search_query, local_path: image.local_path,
        source_page: image.source_page, source_file_url: image.original_url,
        creator: image.creator, credit: image.credit, license: image.license,
        license_url: image.license_url, alt: image.description || `${record.name} photograph`,
        coverage: contextualImagePlaces.has(record.id) ? "place-or-local-context" : "exact-place-or-experience",
        production_usable: image.production_usable ?? image.license !== "Unknown",
        rights_status: image.rights_status || "commons-license-recorded",
        visual_review: image.review_status === "reviewed" ? "reviewed" : "pending-final-review"
      });
      return id;
    });
    const routeVariant = record.replacement ? replacementGeometryById.get(record.replacement.route_variant_id) : null;
    return {
      ...record,
      country: "US",
      coordinates,
      coordinate_order: "longitude_latitude",
      coordinate_source: manualCoordinates[record.id] ? "manual_verified_address" : "openstreetmap_nominatim",
      image_ids: imageIds,
      ratings: { traveler_ratings: Object.fromEntries(PEOPLE.map((person) => [person, null])), average: null, rating_count: 0 },
      researcher_person_fit: Object.fromEntries(PEOPLE.map((person) => [person, personFit(record, person)])),
      included_in_magic_score: record.priority !== "replacement",
      replacement: record.replacement ? { ...record.replacement, route_variant: routeVariant } : undefined,
      data_status: imageIds.length >= 3 ? "complete" : "image-gap"
    };
  });
  const placeById = new Map(productionPlaces.map((record) => [record.id, record]));
  const weatherByDay = new Map(weather.days.map((day) => [day.day, day]));
  const geometryByDay = new Map(geometry.days.map((day) => [day.day, day]));
  const comfort = [3.8, 3.9, 3.9, 4.0, 4.1, 4.3, 4.2, 4.0, 3.9, 3.7, 3.6];
  const days = dayPlans.map((plan) => {
    const routed = geometryByDay.get(plan.day);
    const normal = weatherByDay.get(plan.day);
    if (!routed || !normal) throw new Error(`Missing routed/weather data for day ${plan.day}`);
    const capStatus = routed.baseline_total_minutes >= 205 || routed.planning_total_minutes.high > 210 ? "live-traffic-gated" : routed.baseline_total_minutes >= 185 ? "near-cap" : "comfortable";
    return {
      ...plan,
      day_of_week: new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "America/New_York" }).format(new Date(`${plan.date}T12:00:00-04:00`)),
      drive: {
        legs: routed.legs,
        baseline_total_miles: routed.baseline_total_miles,
        baseline_total_minutes: routed.baseline_total_minutes,
        non_driving_travel_minutes: routed.non_driving_travel_minutes || 0,
        total_travel_minutes_excluding_queues: routed.total_travel_minutes_excluding_queues || routed.baseline_total_minutes,
        planning_total_minutes: routed.planning_total_minutes,
        traffic_risk: routed.risk,
        cap_minutes: 210,
        cap_status: capStatus,
        fallback: plan.fallback
      },
      schedule: plan.schedule.map((item) => scheduleItem(item, placeById)),
      weather: {
        kind: "historical_normal",
        high_c: normal.normal_high_c,
        low_c: normal.normal_low_c,
        precipitation_probability_percent: normal.measurable_precipitation_probability_percent,
        comfort_score: comfort[plan.day - 1],
        station_id: normal.station_id,
        station_name: normal.station_name,
        station_role: normal.station_role,
        source_id: "src-noaa-normals",
        forecast_status: "replace_with_live_forecast_10_days_before"
      }
    };
  });
  const knownCore = productionPlaces
    .filter((record) => record.included_in_magic_score && record.kind !== "live-music-district")
    .reduce((sum, record) => sum + (record.cost.amount_per_person || 0), 0);
  const route = {
    schema_version: "1.0.0",
    route: {
      id: ROUTE_ID, slug: "wild-shore-rockets-folklore-loop", name: ROUTE_NAME, short_name: "Wild Shore & Rockets",
      status: "researched", map_color: "#00A8A8", timezone: "America/New_York",
      start_date: "2026-10-04", end_date: "2026-10-14", airport_date: "2026-10-15",
      origin: { name: "Boston Logan Rental Car Center", coordinates: lodgingNodes["boston-logan-rental"].coordinates },
      destination: { name: "Boston Logan hotel zone", coordinates: lodgingNodes["boston-logan-hotel"].coordinates },
      endpoint_city: "Norfolk, VA",
      direction: "Atlantic ferries and barrier islands south; Norfolk and Richmond apex; Baltimore, Delaware, Sleepy Hollow and coastal Connecticut north",
      countries: ["US"], canada_included: false, total_nights: 11, road_nights: 10, final_boston_nights: 1,
      baseline_total_miles: geometry.route_baseline_total_miles,
      summary: "A warmer-leaning Atlantic loop where ferries replace highway monotony: Long Island marshes and architecture, Asbury pinball and live music, Cape May oddities, Fort Miles, Assateague horses, NASA Wallops, the Chesapeake Bay Bridge-Tunnel, Norfolk and Richmond, Orthodox Sunday, industrial history and an exact-date Sleepy Hollow finale."
    },
    constraints: {
      travelers: 4, cars: 2, cars_follow_same_route: true,
      daily_drive_target_minutes: [120, 180], daily_drive_hard_cap_minutes: 210,
      max_big_nights_out: 4, planned_big_nights_out: 1,
      max_athletic_adrenaline_spots: 2, planned_athletic_adrenaline_spots: 0,
      hike_soft_cap_miles: 6,
      lodging_rooms: [{ count: 1, beds: 1 }, { count: 1, beds: 2 }],
      lodging_priorities: ["safe", "clean", "comfortable", "two-room inventory", "secure parking"],
      visa_policy: "US-only route with no Canada border crossing or J-1 re-entry dependency.",
      budget_target_per_person_usd: 1500,
      budget_excludes: ["lodging", "rental cars", "fuel", "nightlife", "personal shopping"]
    },
    scoring: {
      scale: { min: 1, max: 5, increment: 0.5 }, equal_traveler_weight: true, traveler_ids: PEOPLE,
      route_component_weights_percent: { attraction_and_stop_ratings: 45, excitement_and_uniqueness: 20, driving_comfort: 15, traveler_fairness: 10, cost_and_value: 5, expected_weather: 5 },
      route_ratings: Object.fromEntries(PEOPLE.map((person) => [person, null])),
      driving_comfort_ratings: Object.fromEntries(PEOPLE.map((person) => [person, null])),
      overall_excitement_ratings: Object.fromEntries(PEOPLE.map((person) => [person, null])),
      cost_value_ratings: Object.fromEntries(PEOPLE.map((person) => [person, null])),
      weather_ratings: Object.fromEntries(PEOPLE.map((person) => [person, null])),
      magic_score: null, magic_score_status: "awaiting_traveler_ratings",
      person_specific_route_scores: Object.fromEntries(PEOPLE.map((person) => [person, null]))
    },
    days,
    place_ids: productionPlaces.map((record) => record.id),
    core_place_ids: productionPlaces.filter((record) => record.included_in_magic_score).map((record) => record.id),
    alternative_place_ids: productionPlaces.filter((record) => !record.included_in_magic_score).map((record) => record.id),
    replacement_place_ids: productionPlaces.filter((record) => record.priority === "replacement").map((record) => record.id),
    replacement_options: replacements.variants.map((variant) => ({
      id: variant.id, day: variant.day, replacement_place_id: variant.replacement_place_id,
      replaces_place_ids: variant.replaces_place_ids, baseline_total_miles: variant.baseline_total_miles,
      baseline_total_minutes: variant.baseline_total_minutes, delta_miles: variant.delta_miles,
      delta_minutes: variant.delta_minutes, cap_minutes: variant.cap_minutes, cap_status: variant.cap_status
    })),
    budget: {
      known_core_admission_floor_per_person_usd: Math.round(knownCore * 100) / 100,
      core_admissions_and_ferries_range_per_person_usd: [285, 430],
      food_and_cafes_range_per_person_usd: [650, 900],
      local_parking_tolls_range_per_person_usd: [110, 180],
      controllable_total_range_per_person_usd: [1045, 1510],
      nightlife_range_per_person_usd: [100, 240], nightlife_excluded_from_target: true,
      note: "The route is designed to land around the $1,500 target before lodging, cars, fuel, nightlife and personal shopping. Ferry pricing for two cars is the largest shared variable."
    },
    booking_priorities: [
      { place_id: "pumpkin-blaze", urgency: "required-now", reason: "October 13, 2026 is date-specific and timed tickets are already on sale." },
      { place_id: "cross-sound-ferry", urgency: "early", reason: "Two vehicle spaces on the target Sunday sailing determine the first day." },
      { place_id: "cape-may-lewes-ferry", urgency: "early", reason: "Two vehicle reservations determine the Fort Miles block." },
      { place_id: "cape-may-ghosts", urgency: "when-calendar-opens", reason: "Select the actual October 7 trolley or walking-tour departure." },
      { place_id: "asbury-live-music", urgency: "when-calendar-opens", reason: "Choose a real rock, metal or strong local bill 4-6 weeks out; do not manufacture a generic nightlife stop." },
      { place_id: "lucy-elephant", urgency: "normal", reason: "A timed interior climb protects the Wildwood transfer." },
      { place_id: "fort-miles", urgency: "normal", reason: "Battery 519 capacity and October operations should be reconfirmed." }
    ],
    validation: {
      date_count: days.length, expected_date_count: 11,
      all_baseline_drive_days_at_or_below_cap: days.every((day) => day.drive.baseline_total_minutes <= 210),
      live_traffic_gated_days: days.filter((day) => day.drive.cap_status === "live-traffic-gated").map((day) => day.day),
      place_count: productionPlaces.length, image_count: images.length,
      places_with_fewer_than_3_usable_images: productionPlaces.filter((record) => record.image_ids.length < 3).map((record) => record.id),
      replacement_option_count: replacements.variants.length,
      all_replacement_variants_at_or_below_cap: replacements.variants.every((variant) => variant.baseline_total_minutes <= variant.cap_minutes),
      unfilled_place_ratings: productionPlaces.length * PEOPLE.length,
      hard_closures_or_conflicts: [
        "Cross Sound and Cape May-Lewes sailings are schedule gates, not road-driving time; vehicle check-in and queue buffers remain separate.",
        "Asbury live music is not locked until an actual October 6 bill is published.",
        "Mashomack access must be reconfirmed for seasonal hunting closures.",
        "NASA Wallops can close for mission operations even on a normally open Friday.",
        "The B&O Mile One 11:30 train is incompatible with Richmond Liturgy and is not promised.",
        "David Rockefeller Creative Arts Center is replacement-only until October 13 exhibition hours are confirmed.",
        "All no-traffic routing must be replaced by live navigation each morning; days flagged live-traffic-gated lose optional stops before the bed-to-bed cap is exceeded."
      ],
      route_lock_status: "research-complete-bookings-pending"
    }
  };

  const geojson = { type: "FeatureCollection", name: ROUTE_SLUG, features: [
    ...days.flatMap((day) => day.drive.legs.map((leg) => ({ type: "Feature", id: leg.id, properties: { feature_kind: "drive_leg", mode: leg.mode, route_id: ROUTE_ID, day: day.day, date: day.date, from: leg.from, to: leg.to, distance_miles: leg.distance_miles, baseline_minutes: leg.baseline_minutes, display_duration_minutes: leg.display_duration_minutes, counts_toward_drive_cap: leg.counts_toward_drive_cap, traffic_risk: leg.traffic_risk, map_color: route.route.map_color }, geometry: leg.geometry }))),
    ...replacements.variants.filter((variant) => variant.geometry).map((variant) => ({ type: "Feature", id: variant.id, properties: { feature_kind: "replacement_drive_variant", route_id: ROUTE_ID, day: variant.day, replacement_place_id: variant.replacement_place_id, replaces_place_ids: variant.replaces_place_ids, baseline_total_miles: variant.baseline_total_miles, baseline_total_minutes: variant.baseline_total_minutes, delta_minutes: variant.delta_minutes, cap_status: variant.cap_status, map_color: route.route.map_color }, geometry: variant.geometry })),
    ...productionPlaces.map((record) => ({ type: "Feature", id: record.id, properties: { feature_kind: "place", route_id: ROUTE_ID, place_id: record.id, name: record.name, city: record.city, state: record.state, visit_date: record.visit_date, priority: record.priority, included_in_magic_score: record.included_in_magic_score }, geometry: { type: "Point", coordinates: record.coordinates } })),
    ...Object.entries(geometry.nodes).map(([id, node]) => ({ type: "Feature", id: `node-${id}`, properties: { feature_kind: "route_node", route_id: ROUTE_ID, node_id: id, name: node.name }, geometry: { type: "Point", coordinates: node.coordinates } }))
  ] };

  await Promise.all([
    writeFile(path.join(ROUTE_DIR, "place-seed.json"), `${JSON.stringify({ schema_version: "1.0.0", route_id: ROUTE_ID, places: seedPlaces }, null, 2)}\n`),
    writeFile(path.join(ROUTE_DIR, "sources.json"), `${JSON.stringify({ schema_version: "1.0.0", route_id: ROUTE_ID, verified_at: verifiedAt, sources }, null, 2)}\n`),
    writeFile(path.join(ROUTE_DIR, "places.json"), `${JSON.stringify({ schema_version: "1.0.0", route_id: ROUTE_ID, places: productionPlaces }, null, 2)}\n`),
    writeFile(path.join(ROUTE_DIR, "images.json"), `${JSON.stringify({ schema_version: "1.0.0", route_id: ROUTE_ID, image_policy: "Downloaded Wikimedia Commons derivatives with per-file attribution; contextual coverage is explicitly labeled and every selected image receives final visual review.", images }, null, 2)}\n`),
    writeFile(path.join(ROUTE_DIR, "route.json"), `${JSON.stringify(route, null, 2)}\n`),
    writeFile(path.join(ROUTE_DIR, "route.geojson"), `${JSON.stringify(geojson, null, 2)}\n`)
  ]);
  await buildEnergyRoute03({ root: ROOT, routeDir: ROUTE_DIR });
  console.log(`Built ${ROUTE_NAME}: ${productionPlaces.length} places, ${images.length} images, ${days.length} days.`);
}

main().catch((error) => { console.error(error); process.exitCode = 1; });
